      "El navegador lo renderiza con fondo amarillo por defecto (background: yellow, color: black).",
      "Es un elemento inline: no genera saltos de línea.",
      "Su semántica es de relevancia contextual, no de importancia.",
      "Se usa mucho en resultados de búsqueda (Google, sitios internos).",
