      "Confundirlo con <strong> (importancia) o <em> (énfasis).",
      "Usarlo en párrafos completos (pierde efecto).",
      "Abusar: si todo está resaltado, nada destaca.",
      "Usarlo para énfasis (ahí van <em> o <strong>).",
