        "descripcion": "",
        "code": "<article>\n  <header>\n    <h1>Cómo aprender HTML</h1>\n    <p>\n      Por <strong>Ana Pérez</strong> ·\n      <time datetime=\"2026-10-08\">8 de octubre de 2026</time>\n    </p>\n  </header>\n  <p>...</p>\n</article>",
