      "Usar value en checkboxes sin name correcto.",
      "Poner el mismo id en varios inputs (inválido).",
      "Usar autocomplete=\"off\" en campos de login (mala UX).",
      "Confundir <input type=\"submit\"> con <button type=\"submit\"> (mejor <button>).",
      "Usar align (obsoleto): usar CSS.",
