    "fuente": "MDN – <input>: https://developer.mozilla.org/es/docs/Web/HTML/Element/input MDN – Tipos de input: https://developer.mozilla.org/es/docs/Web/HTML/Element/input#tipo WHATWG HTML Living Standard – The input element: https://html.spec.whatwg.org/multipage/input.html#the-input-element W3C – HTML5: The input element web.dev – Forms: https://web.dev/learn/forms",
