    "fuente": "MDN – <output>: https://developer.mozilla.org/es/docs/Web/HTML/Element/output WHATWG HTML Living Standard – The output element: https://html.spec.whatwg.org/multipage/form-elements.html#the-output-element W3C – HTML5: The output element web.dev – Forms: https://web.dev/learn/forms",
