      "Es un elemento vacío: no tiene contenido ni cierre.",
      "Se comporta como reemplazado: ocupa un área rectangular.",
      "Puede tener múltiples <embed> en una misma página.",
      "Los atributos aceptados son limitados (no acepta atributos globales en algunos casos).",
