      "Usa el formato WebVTT (.vtt) para definir las pistas.",
      "Cada <track> define una pista (subtítulos, descripciones, etc.).",
      "El atributo kind define el tipo de pista.",
      "srclang define el idioma; label define el nombre visible.",
      "default marca la pista activa por defecto.",
